unordered_set<int> values;

for (int i = 0; i < n; i++) {
  values.insert(arr[i]); 
}

int longest = 0;

for (int x : values) {
  // Only begin counting at the start of a new sequence
  if (values.contains(x - 1)) continue;

  int y = x;
  while (values.contains(y)) y++;

  int length = y - x;
  if (length > longest) longest = length;
}
```

